        int moves_remain = moves_n - moves_spent;

        int max_b_start = min((int)b_indices.size(), moves_remain);
        for (int b_start = 0; b_start <= max_b_start; ++b_start) {
            int b_start_moves_spent = b_start;
            moves_spent = c_start_moves_spent + b_start_moves_spent;
            moves_remain = moves_n - moves_spent;

            vector<char> new_s(s.begin(), s.end());
            for (int i_i_c = 0; i_i_c < c_start; ++i_i_c) {
                int i_c = c_indices[i_i_c];
                new_s[i_c] = _A;
            }
            for (int i_i_b = 0; i_i_b < b_start; ++i_i_b) {
                int i_b = b_indices[i_i_b];
                new_s[i_b] = _A;
            }

            long long curr_best_score = _find_best_score_can_make_with_fixed_starts(new_s, moves_remain);
            if (curr_best_score > best_score) best_score = curr_best_score;
        }
    }

    return best_score;
}

tuple<vector<int>, vector<int>, vector<int>> _compute_abc_indices(const string &s) {
    vector<int> a_indices, b_indices, c_indices;
    for (int i = 0; i < (int)s.size(); ++i) {
        char ch = s[i];
        if (ch == _A) a_indices.push_back(i);
        else if (ch == _B) b_indices.push_back(i);
        else c_indices.push_back(i);
    }
    return make_tuple(a_indices, b_indices, c_indices);
}

vector<char> _get_curr_s(const vector<char> &s, const vector<int> &a_indices, int a_stop, const vector<int> &c_indices, int c_stop) {
    vector<char> res = s;
    for (int i_i_a = 0; i_i_a < a_stop; ++i_i_a) {
        int i_a = a_indices[i_i_a];
        res[i_a] = _A;
    }
    for (int i_i_a = a_stop; i_i_a < (int)a_indices.size(); ++i_i_a) {
        int i_a = a_indices[i_i_a];
        res[i_a] = _B;
    }
    for (int i_i_c = 0; i_i_c < c_stop; ++i_i_c) {
        int i_c = c_indices[i_i_c];
        res[i_c] = _C;
    }
    for (int i_i_c = c_stop; i_i_c < (int)c_indices.size(); ++i_i_c) {
        int i_c = c_indices[i_i_c];
        res[i_c] = _B;
    }
    return res;
}

long long _get_curr_score_slow_way(const vector<char> &s) {
    long long curr_score = 0;
    long long a_accumulated = 0;
    for (char ch : s) {
        if (ch == _A) {
            a_accumulated += 1;
        } else if (ch == _B) {
            curr_score += a_accumulated;
        }
    }
    return curr_score;
}

vector<int> _compute_a_before(const string &s) {
    int n = (int)s.size();
    vector<int> acc(n);
    int sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += (s[i] == _A ? 1 : 0);
        acc[i] = sum;
    }
    vector<int> result(n + 1);
    result[0] = 0;
    for (int i = 0; i < n; ++i) {
        result[i + 1] = acc[i];
    }
    result.pop_back();
    return result;
}

vector<int> _compute_b_after(const string &s) {
    int n = (int)s.size();
    vector<int> acc(n);
    int sum = 0;
    for (int i = n - 1; i >= 0; --i) {
        sum += (s[i] == _B ? 1 : 0);
        acc[i] = sum;
    }
    vector<int> result(n);
    for (int i = 0; i < n; ++i) {
        result[i] = acc[i];
    }
    vector<int> shifted(n);
    for (int i = 0; i < n - 1; ++i) {
        shifted[i] = result[i + 1];
    }
    shifted[n - 1] = 0;
    return shifted;
}

long long _find_best_score_can_make_with_fixed_starts(const vector<char> &s_vec, int moves_n) {
    vector<char> s = s_vec;

    long long best_score = (long long)-9e18;

    string s_str(s.begin(), s.end());
    vector<int> a_indices, b_indices, c_indices;
    tie(a_indices, b_indices, c_indices) = _compute_abc_indices(s_str);

    int a_n = (int)a_indices.size();
    int c_n = (int)c_indices.size();

    int max_a_stop = (int)a_indices.size();
    int max_c_stop = (int)c_indices.size();

    auto get_c_stop_by_moves_remain = [&](int moves_remain) {
        int min_c_stop = max_c_stop - moves_remain;
        if (min_c_stop < 0) min_c_stop = 0;
        int c_stop = min_c_stop;
        return c_stop;
    };

    int first_c_stop = get_c_stop_by_moves_remain(moves_n);
    vector<char> new_s_vec = _get_curr_s(s, a_indices, max_a_stop, c_indices, first_c_stop);
    long long curr_score = _get_curr_score_slow_way(new_s_vec);

    if (curr_score > best_score) best_score = curr_score;

    string new_s_str(new_s_vec.begin(), new_s_vec.end());
    vector<int> old_a_before = _compute_a_before(new_s_str);
    string replaced = new_s_str;
    for (char &ch : replaced) if (ch == _C) ch = _B;
    vector<int> old_b_after_if_all_c_are_b = _compute_b_after(replaced);

    int curr_b_to_c_before_a = 0;
    int curr_a_to_b_after_c = 0;

    int prev_c_stop = -1;
    int c_stop = first_c_stop;
    int c_stop_moves_spent = max_c_stop - c_stop;

    int min_a_stop = max_a_stop - moves_n;
    if (min_a_stop < 0) min_a_stop = 0;
    for (int a_stop = max_a_stop - 1; a_stop >= min_a_stop; --a_stop) {
        int a_stop_moves_spent = max_a_stop - a_stop;
        int moves_spent = a_stop_moves_spent;
        int moves_remain = moves_n - moves_spent;

        int curr_a_index = a_indices[a_stop];
        int curr_b_to_c = c_stop;
        if (curr_b_to_c_before_a < curr_b_to_c &&
            c_indices[curr_b_to_c_before_a] < curr_a_index) {
            while (curr_b_to_c_before_a < curr_b_to_c &&
                   c_indices[curr_b_to_c_before_a] < curr_a_index) {
                curr_b_to_c_before_a += 1;
            }
        } else if (curr_b_to_c_before_a > 0 &&
                   c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
            while (curr_b_to_c_before_a > 0 &&
                   c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
                curr_b_to_c_before_a -= 1;
            }
        }

        int prev_a_stop_moves_spent = a_stop_moves_spent - 1;
        int curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a;
        int new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a;
        int b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after;
        curr_score -= b_after;
        curr_score += old_a_before[curr_a_index];

        prev_c_stop = c_stop;
        c_stop = get_c_stop_by_moves_remain(moves_remain);
        c_stop_moves_spent = max_c_stop - c_stop;

        if (c_stop - prev_c_stop == 1) {
            int prev_c_index = c_indices[prev_c_stop];
            int curr_a_to_b = a_n - a_stop;
            if (curr_a_to_b_after_c < curr_a_to_b &&
                a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                while (curr_a_to_b_after_c < curr_a_to_b &&
                       a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                    curr_a_to_b_after_c += 1;
                }
            } else if (curr_a_to_b_after_c > 0 &&
                       a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                while (curr_a_to_b_after_c > 0 &&
                       a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                    curr_a_to_b_after_c -= 1;
                }
            }

            int a_to_b_before = curr_a_to_b - curr_a_to_b_after_c;
            int curr_a_before = old_a_before[prev_c_index] - a_to_b_before;
            curr_score -= curr_a_before;
        }

        if (curr_score > best_score) best_score = curr_score;
    }

    return best_score;
}

